STEPS = ["download", "verify", "write_B", "mark_B_pending", "reboot", "selftest", "commit_B"]

def run(cut_at, bug=False):
    s = {"active": "A", "pending": None}
    for i, step in enumerate(STEPS):
        if i == cut_at:          # 여기서 전원이 끊긴다
            break
        if step == "mark_B_pending":
            s["pending"] = "B"
        if step == "commit_B":
            s["active"], s["pending"] = "B", None
    boot = s["active"]
    if s["pending"] and bug:
        boot = "B"               # 버그: 확정 전인데 B 로 부팅
    return boot == s["active"]

for bug in (False, True):
    fails = [STEPS[c] for c in range(len(STEPS)) if not run(c, bug)]
    print("bug" if bug else "ok ", "끊긴 지점 7곳 중 실패:", fails or "없음")
